/**
 * EHT model simulation initialization.
 * Sets up the initial state with cells and links.
 */

import { SeededRandom } from '@/core/math/random';
import { createBasalGeometry } from '@/core/math';
import type { EHTSimulationState } from '../types';
import type { EHTParams, GlobalEvent, ParameterChangeEvent } from '../params/types';
import { CellCyclePhase } from '../params/types';
import { computeEllipseFromPerimeter, ramanujanPerimeter } from '../params/geometry';
import { createCell, type CreateCellInput } from './cell';
import { evaluateUnitAwareFormula } from '../compat/formula-units';

/**
 * Scan formula maps on params and generate synthetic events.
 * Global formulas → GlobalEvent with period:'dt' appended to global_events.
 * Per-cell formulas → ParameterChangeEvent with period:'dt' appended to events_v2.
 * Mutates the params object in place.
 *
 * Also evaluates each formula at t=0 to set the initial param value,
 * so that init (geometry, cell positions) uses the formula's t=0 value.
 */
export function generateFormulaEvents(params: EHTParams): void {
  // Generate global events from general.formulas
  for (const [fieldName, formula] of Object.entries(params.general.formulas)) {
    const initValue = (params.general as unknown as Record<string, unknown>)[fieldName];
    if (typeof initValue !== 'number') continue;

    const event: GlobalEvent = {
      id: `__formula_${fieldName}`,
      start: 0,
      end: Infinity,
      period: 'dt',
      target_parameter: `general.${fieldName}`,
      formula,
      init_value: initValue,
    };
    params.general.global_events.push(event);

    // Evaluate at t=0 so init uses the formula's initial value
    try {
      const t0Value = evaluateUnitAwareFormula({
        formula,
        targetParameter: `general.${fieldName}`,
        oldValue: initValue,
        initValue,
        t: 0,
        dt: 0,
        params,
      });
      if (typeof t0Value === 'number' && isFinite(t0Value)) {
        (params.general as unknown as Record<string, unknown>)[fieldName] = t0Value;
      }
    } catch { /* keep original value on error */ }
  }

  // Generate per-cell events from cell_types.*.formulas
  for (const [, cellType] of Object.entries(params.cell_types)) {
    if (!cellType.formulas || Object.keys(cellType.formulas).length === 0) continue;

    if (!cellType.events_v2) {
      cellType.events_v2 = [];
    }

    for (const [fieldName, formula] of Object.entries(cellType.formulas)) {
      const initValue = (cellType as unknown as Record<string, unknown>)[fieldName];
      if (typeof initValue !== 'number') continue;

      const event: ParameterChangeEvent = {
        id: `__formula_${fieldName}`,
        type: 'parameter_change',
        start: 0,
        end: Infinity,
        period: 'dt',
        probability: '1',
        prereq: null,
        cell_cycle_phase: CellCyclePhase.Any,
        target_parameter: fieldName,
        formula,
        init_value: initValue,
      };
      cellType.events_v2.push(event);

      // Evaluate at t=0 so init uses the formula's initial value
      try {
        const t0Value = evaluateUnitAwareFormula({
          formula,
          targetParameter: fieldName,
          oldValue: initValue,
          initValue,
          t: 0,
          dt: 0,
          params,
          cellTypeParams: cellType,
        });
        if (typeof t0Value === 'number' && isFinite(t0Value)) {
          (cellType as unknown as Record<string, unknown>)[fieldName] = t0Value;
        }
      } catch { /* keep original value on error */ }
    }
  }
}

/**
 * Initialize the EHT simulation with cells.
 * Creates initial cell positions, assigns cell types, and establishes links.
 */
export function initializeEHTSimulation(
  params: EHTParams,
  state: EHTSimulationState,
  rng: SeededRandom
): void {
  const pg = params.general;

  // Store a mutable simulation-local copy of params
  state.params = structuredClone(params);

  // Generate synthetic events from formula maps
  generateFormulaEvents(state.params);

  // Compute and store geometry from perimeter/aspect_ratio
  const geometry = computeEllipseFromPerimeter(pg.perimeter, pg.aspect_ratio);
  state.geometry = {
    curvature_1: geometry.curvature_1,
    curvature_2: geometry.curvature_2,
  };

  const { curvature_1, curvature_2 } = state.geometry;

  // Create pre-computed basal geometry representation
  state.basalGeometry = createBasalGeometry(curvature_1, curvature_2, 360);

  // Collect all cell type entries and compute total N
  const cellTypeEntries = Object.entries(params.cell_types);
  const totalN = cellTypeEntries.reduce((sum, [, ct]) => sum + ct.N_init, 0);

  // first we distribute cell positions along a periodic domain from [-1, 1] in x
  // later we will wrap it around to the curved basal membrane

  const locations: [number,string][] = [];
  for(let i = 0; i < totalN; i++) {
    
    locations.push([-1 + (2 * (i)) / totalN, ""]);
  }

  // sort cell type entried by weather or not they have a location specified
  cellTypeEntries.sort((a, b) => {
    const aHasLoc = a[1].location !== "" ? 1 : 0;
    const bHasLoc = b[1].location !== "" ? 1 : 0;
    return bHasLoc - aHasLoc;
  });

  // assign locations to cell types that have them specified
  for(const [typeKey, cellType] of cellTypeEntries) {
    if(cellType.location !== "") {
      let locValue: number;
      // console.log("Assigning locations for cell type", typeKey, "with location", cellType.location);
      if(cellType.location === "top") {
        locValue = 1;
      } else if(cellType.location === "bottom") {
        locValue = 0;
      } else {
        locValue = parseFloat(cellType.location);
        if(isNaN(locValue) || locValue < -1 || locValue > 1) {
          locValue = 0.0;
        }
      }

      // sort locations by closeness to desired location, using modulo on [-1, 1]
      locations.sort((a, b) => {
        return Math.min(Math.abs(a[0] - locValue),Math.abs(a[0] + 2 - locValue)) -
          Math.min(Math.abs(b[0] - locValue),Math.abs(b[0] + 2 - locValue));
      });

      // assign the closest unassigned locations to this cell type
      let assigned = 0;
      for(let i = 0; i < locations.length && assigned < cellType.N_init; i++) {
        if(locations[i][1] === "") {
          locations[i] = [locations[i][0], typeKey];
          assigned++;
        }
      }
    }
  }

  // sort locations again by x value
  locations.sort((a, b) => a[0] - b[0]);

  // fill in unassigned locations with remaining cell types
  let assignIndex = 0;
  for(let i = 0; i < locations.length; i++) {
    if(locations[i][1] !== "") continue; // Check if already assigned
    while(assignIndex < cellTypeEntries.length) {
      const [typeKey, cellType] = cellTypeEntries[assignIndex];
      const assignedCount = locations.filter(loc => loc[1] === typeKey).length; // Count in locations array
      if(assignedCount < cellType.N_init) {
        locations[i] = [locations[i][0], typeKey]; // Assign type key to location
        break;
      } else {
        assignIndex++;
      }
    }
  }

  // Sort locations back to original order
  locations.sort((a, b) => a[0] - b[0]);

  // For line geometry (curvature = 0), use w_init directly
  // For curved geometry, compute perimeter from curvatures
  const isLineGeometry = curvature_1 === 0 && curvature_2 === 0;
  const perimeter = isLineGeometry
    ? pg.w_init * 4  // Use a finite value for arc length calculations
    : ramanujanPerimeter(Math.abs(1 / curvature_1), Math.abs(1 / curvature_2));

  const w = pg.full_circle ? perimeter : pg.w_init;
  const h = pg.h_init;

  // For negative aspect ratio, flip normal direction to place cells outside the ellipse
  const normalSign = pg.aspect_ratio < 0 ? -1 : 1;

  // Generate initial cell inputs (basal, apical, nucleus positions)
  const cellInputs: CreateCellInput[] = [];
  const typeAssignments: string[] = [];
  for (let i = 0; i < totalN; i++) {
    // For line geometry, distribute cells along [-w/2, w/2]
    // For curved geometry, use arc length parameterization
    const arcLength = isLineGeometry
      ? locations[i][0] * (w / 2)
      : locations[i][0] * (w / 2) + perimeter / 4;

    // Get the basal point directly from arc length
    const basalPoint = state.basalGeometry.getPointAtArcLength(arcLength);

    // Get the normal at this basal point (flip for negative aspect ratio)
    const normal = state.basalGeometry.getNormal(basalPoint).scale(normalSign);

    // Compute apical point along normal at height h
    const apicalPoint = basalPoint.add(normal.scale(h));

    // Compute nucleus position at random height between basal and apical
    const nucleusHeight = rng.random(h / 3, (2 * h) / 3);
    const nucleusPosition = basalPoint.add(normal.scale(nucleusHeight));

    cellInputs.push({
      basalPoint,
      apicalPoint,
      nucleusPosition,
    });
    typeAssignments.push(locations[i][1]);
  }

  // Create cells
  state.cells = [];
  for (let i = 0; i < cellInputs.length; i++) {
    const typeKey = typeAssignments[i];
    const cellType = state.params!.cell_types[typeKey];
    if (!cellType) {
      console.warn("No cell type found for key", typeKey);
      continue;
    }
    const cell = createCell(
      state.params!,
      state,
      rng,
      cellInputs[i],
      cellType,
      typeKey
    );

    state.cells.push(cell);
  }

  // Create initial links between adjacent cells
  for (let i = 0; i < state.cells.length - 1; i++) {
    // Use average of both cell types' apical junction init
    const cellTypeI = params.cell_types[state.cells[i].typeIndex];
    const cellTypeJ = params.cell_types[state.cells[i + 1].typeIndex];
    const apicalJunctionInit = (cellTypeI.apical_junction_init + cellTypeJ.apical_junction_init) / 2;
    state.ap_links.push({
      l: i,
      r: i + 1,
      rl: apicalJunctionInit,
    });
    state.ba_links.push({
      l: i,
      r: i + 1,
    });
  }

  // If simulating a closed ring, connect the last and first cells as well.
  if (pg.full_circle && state.cells.length > 2) {
    const last = state.cells.length - 1;
    const cellTypeLast = params.cell_types[state.cells[last].typeIndex];
    const cellTypeFirst = params.cell_types[state.cells[0].typeIndex];
    const apicalJunctionInit = (cellTypeLast.apical_junction_init + cellTypeFirst.apical_junction_init) / 2;
    state.ap_links.push({
      l: last,
      r: 0,
      rl: apicalJunctionInit,
    });
    state.ba_links.push({
      l: last,
      r: 0,
    });
  }
}
