/**
 * Special event handler registry.
 * Maps special event names to their handler functions.
 */
const specialEventHandlers: Record<SpecialEventName, (state: EHTSimulationState, cellIndex: number) => void> = {
  'lose_apical_adhesion': processLoseApicalAdhesion,
  'lose_basal_adhesion': processLoseBasalAdhesion,
  'lose_apical_interface': processLoseApicalInterface,
  'start_running': processStartRunning,
  'cell_division': () => {}, // Handled as deferred event in processV2Events
  'cell_cycle_reset': () => {}, // Handled as deferred event in processV2Events
};

/**
 * Evaluate a math.js formula for a parameter change event.
 * Scope includes old_value, t, dt, period, general params, and cell type params.
 */
function evaluateFormula(
  params: EHTParams,
  targetParameter: string,
  formula: string,
  oldValue: number,
  t: number,
  dt: number,
  period: number,
  birthTime: number,
  generalParams?: import('../params/types').EHTGeneralParams,
  cellTypeParams?: EHTCellTypeParams,
  initValue?: number,
  cellContext?: { alpha: number; r: number; delta: number },
  constants?: Record<string, number>
): number {
  try {
    return evaluateUnitAwareFormula({
      formula,
      targetParameter,
      oldValue,
      t,
      dt,
      period: period || 1,
      birthTime,
      initValue,
      cellContext,
      generalParams,
      cellTypeParams,
      params: { ...params, constants: constants ?? params.constants },
    });
  } catch (error) {
    console.error(`[Events] Failed to evaluate formula "${formula}":`, error);
    return oldValue; // Return unchanged value on error
  }
}

/**
 * Get a cell parameter value by path.
 */
function getCellParameter(cell: CellState, path: string): number | undefined {
  switch (path) {
    case 'stiffness_nuclei_apical':
      return cell.stiffness_nuclei_apical;
    case 'stiffness_nuclei_basal':
      return cell.stiffness_nuclei_basal;
    case 'stiffness_straightness':
      return cell.stiffness_straightness;
    case 'stiffness_apical_apical':
      return cell.stiffness_apical_apical;
    case 'R_soft':
      return cell.R_soft;
    case 'R_hard':
      return cell.R_hard;
    case 'eta_A':
      return cell.eta_A;
    case 'eta_B':
      return cell.eta_B;
    case 'running_mode':
      return cell.running_mode;
    case 'apical_cytos_strain':
      return cell.apical_cytos_strain;
    case 'basal_cytos_strain':
      return cell.basal_cytos_strain;
    case 'k_apical_junction':
      return cell.k_apical_junction;
    default:
      console.warn(`[Events] Unknown cell parameter: ${path}`);
      return undefined;
  }
}

/**
 * Set a cell parameter value by path.
 */
function setCellParameter(cell: CellState, path: string, value: number): void {
  switch (path) {
    case 'stiffness_nuclei_apical':
      cell.stiffness_nuclei_apical = value;
      break;
    case 'stiffness_nuclei_basal':
      cell.stiffness_nuclei_basal = value;
      break;
    case 'stiffness_straightness':
      cell.stiffness_straightness = value;
      break;
    case 'stiffness_apical_apical':
      cell.stiffness_apical_apical = value;
      break;
    case 'R_soft':
      cell.R_soft = value;
      break;
    case 'R_hard':
      cell.R_hard = value;
      break;
    case 'eta_A':
      cell.eta_A = value;
      break;
    case 'eta_B':
      cell.eta_B = value;
      break;
    case 'running_mode':
      cell.running_mode = value;
      break;
    case 'apical_cytos_strain':
      cell.apical_cytos_strain = value;
      break;
    case 'basal_cytos_strain':
      cell.basal_cytos_strain = value;
      break;
    case 'k_apical_junction':
      cell.k_apical_junction = value;
      break;
    default:
      console.warn(`[Events] Unknown cell parameter: ${path}`);
  }
}

/**
 * Check if an event's prerequisites are satisfied for a cell.
 */
function prereqSatisfied(
  eventDef: EventDefinition,
  cell: CellState
): boolean {
  // No prereq required
  if (!eventDef.prereq) {
    return true;
  }

  // Check if prereq event has fired for this cell
  const prereqState = cell.event_states?.[eventDef.prereq];
  return prereqState?.has_fired === true;
}

function schedulePendingDependentEvent(
  eventState: CellEventState,
  eventDef: EventDefinition,
  cell: CellState,
  rng: SeededRandom,
  generalParams?: import('../params/types').EHTGeneralParams,
  cellTypeParams?: EHTCellTypeParams,
  constants?: Record<string, number>
): void {
  if (!eventState.pending_dependency || !eventDef.prereq) {
    return;
  }

  const prereqState = cell.event_states?.[eventDef.prereq];
  if (!prereqState?.has_fired) {
    return;
  }

  const start = prereqState.last_fire_time;
  if (eventDef.end === -1 || (isFinite(eventDef.end) && start > eventDef.end)) {
    eventState.pending_dependency = false;
    eventState.trigger_time = Infinity;
    return;
  }

  const prob = evaluateProbabilityFormula(eventDef.probability, generalParams, cellTypeParams, constants);
  if (rng.random() > prob) {
    eventState.pending_dependency = false;
    eventState.trigger_time = Infinity;
    return;
  }

  eventState.pending_dependency = false;
  if (eventDef.period !== 0) {
    eventState.trigger_time = start;
  } else if (isFinite(eventDef.end)) {
    eventState.trigger_time = rng.random(start, eventDef.end);
  } else {
    eventState.trigger_time = start;
  }
}

/**
 * Check if an event should fire for a cell at the current time.
 */
function shouldEventFire(
  eventState: CellEventState,
  eventDef: EventDefinition,
  cell: CellState,
  t: number,
  dt: number
): boolean {
  // Check cell cycle phase requirement
  if (!satisfiesCellCyclePhase(cell, eventDef.cell_cycle_phase)) {
    return false;
  }

  // Check prerequisites
  if (!prereqSatisfied(eventDef, cell)) {
    return false;
  }

  // Check if event was skipped (trigger_time is Infinity)
  if (!isFinite(eventState.trigger_time) || eventState.pending_dependency) {
    return false;
  }

  // One-time event
  if (eventDef.period === 0) {
    if (eventState.has_fired) return false;
    // Phase-only trigger: start=0, end=0 → trigger_time=0, fire when phase is satisfied
    if (eventState.trigger_time === 0) return true;
    // Fire if we just crossed the trigger time
    return t <= eventState.trigger_time && t + dt > eventState.trigger_time;
  }

  // Periodic event — active window semantics
  const effectivePeriod = resolveEffectivePeriod(eventDef.period, dt);

  // Active window check
  const activeStart = eventDef.prereq ? eventState.trigger_time : eventDef.start;
  if (t < activeStart) return false;
  if (eventDef.end !== -1 && isFinite(eventDef.end) && t > eventDef.end) return false;

  // First fire in this cycle
  if (!eventState.has_fired) return true;

  // Subsequent fires
  if (t - eventState.last_fire_time >= effectivePeriod) return true;

  return false;
}

/**
 * Process a parameter change event for a cell.
 */
function processParameterChangeEvent(
  event: ParameterChangeEvent,
  eventState: CellEventState,
  cell: CellState,
  state: EHTSimulationState,
  params: EHTParams,
  t: number,
  dt: number,
  generalParams?: import('../params/types').EHTGeneralParams,
  cellTypeParams?: EHTCellTypeParams,
  constants?: Record<string, number>
): void {
  const oldValue = getCellParameter(cell, event.target_parameter);
  if (oldValue === undefined) {
    return;
  }

  // Compute cell spatial context for formula scope
  const center = state.basalGeometry.center;
  const cx = cell.pos.x - center.x;
  const cy = cell.pos.y - center.y;
  const alpha = Math.atan2(cx, -cy);
  const r = Math.sqrt(cx * cx + cy * cy);
  const posVec = Vector2.from(cell.pos);
  const proj = state.basalGeometry.projectPoint(posVec);
  const nGeom = state.basalGeometry.getNormal(proj);
  const delta = nGeom.x * (cell.pos.x - proj.x) + nGeom.y * (cell.pos.y - proj.y);
  const cellContext = { alpha, r, delta };

  const effectivePeriod = resolveEffectivePeriod(event.period, dt);
  const newValue = evaluateFormula(
    state.params ?? params,
    event.target_parameter,
    event.formula,
    oldValue,
    t,
    dt,
    effectivePeriod,
    cell.birth_time,
    generalParams,
    cellTypeParams,
    event.init_value,
    cellContext,
    constants
  );
  setCellParameter(cell, event.target_parameter, newValue);
  if (event.id === 'inm_contract_apical') {
    cell.has_inm = true;
  }

  // Update event state
  eventState.has_fired = true;
  eventState.last_fire_time = t;
  eventState.fire_count++;
}

/**
 * Process a special event for a cell.
 */
function processSpecialEvent(
  event: SpecialEvent,
  state: EHTSimulationState,
  cellIndex: number
): void {
  const handler = specialEventHandlers[event.special_name];
  if (handler) {
    handler(state, cellIndex);
  } else {
    console.warn(`[Events] Unknown special event: ${event.special_name}`);
  }
}

/**
 * Process all v1.1.0 events for the current timestep.
 */
export function processV2Events(
  state: EHTSimulationState,
  params: EHTParams,
  dt: number,
  rng: SeededRandom
): void {
  const t = state.t;

  // Terminal events: once one fires for a cell, skip remaining terminal events
  const TERMINAL_EVENTS = new Set<SpecialEventName>(['cell_division', 'cell_cycle_reset']);

  // Track deferred events (processed after main loop)
  const constrictedTypes = new Set<string>();
  const cellsToReset: number[] = [];
  const cellsToDivide: number[] = [];

  for (let i = 0; i < state.cells.length; i++) {
    const cell = state.cells[i];
    // Use state.params (has synthetic formula events) if available, fall back to params
    const effectiveParams = state.params ?? params;
    const cellType = effectiveParams.cell_types[cell.typeIndex] as EHTCellTypeParams;

    // Get effective events (merged default + per-type)
    const { orderedEvents, hasErrors } = analyzeEventDependencies(getEffectiveEvents(effectiveParams.general, cellType));
    const effectiveEvents = hasErrors
      ? getEffectiveEvents(effectiveParams.general, cellType)
      : orderedEvents;

    // Skip if no events
    if (effectiveEvents.length === 0 || !cell.event_states) {
      continue;
    }

    let terminalFired = false;

    for (const eventDef of effectiveEvents) {
      // Skip remaining terminal events once one has fired for this cell
      if (terminalFired && eventDef.type === 'special' && TERMINAL_EVENTS.has(eventDef.special_name)) {
        continue;
      }

      const eventState = cell.event_states[eventDef.id];
      if (!eventState) {
        continue;
      }

      schedulePendingDependentEvent(
        eventState,
        eventDef,
        cell,
        rng,
        effectiveParams.general,
        cellType,
        effectiveParams.constants
      );

      if (shouldEventFire(eventState, eventDef, cell, t, dt)) {
        if (eventDef.type === 'parameter_change') {
          processParameterChangeEvent(eventDef, eventState, cell, state, params, t, dt, params.general, cellType, params.constants);
        } else if (eventDef.type === 'special') {
          // Deferred events: collect indices and process after main loop
          if (eventDef.special_name === 'lose_apical_interface') {
            constrictedTypes.add(cell.typeIndex);
            eventState.has_fired = true;
            eventState.last_fire_time = t;
            eventState.fire_count++;
          } else if (eventDef.special_name === 'cell_cycle_reset') {
            cellsToReset.push(i);
            eventState.has_fired = true;
            eventState.last_fire_time = t;
            eventState.fire_count++;
            terminalFired = true;
          } else if (eventDef.special_name === 'cell_division') {
            cellsToDivide.push(i);
            eventState.has_fired = true;
            eventState.last_fire_time = t;
            eventState.fire_count++;
            terminalFired = true;
          } else {
            processSpecialEvent(eventDef, state, i);
            eventState.has_fired = true;
            eventState.last_fire_time = t;
            eventState.fire_count++;
          }
        }
      }
    }

    // Update running state
    updateRunningState(cell, state);
  }

  // Process cell cycle resets first (in-place, no new cells)
  for (const cellIndex of cellsToReset) {
    processCellCycleReset(state, params, rng, cellIndex);
  }

  // Process cell divisions (may add new cells)
  for (const cellIndex of cellsToDivide) {
    divideSingleCell(state, params, rng, cellIndex);
  }

  // Process apical constriction once per cell type
  for (const typeIndex of constrictedTypes) {
    const cellIdx = state.cells.findIndex(c => c.typeIndex === typeIndex);
    if (cellIdx !== -1) {
      processLoseApicalInterface(state, cellIdx);
    }
  }
}

/**
 * Process a cell cycle reset event.
 * Resets the cell's cycle without dividing — creates a fresh cell in-place,
 * preserving the cell's ID, and re-initializes event states.
 */
function processCellCycleReset(
  state: EHTSimulationState,
  params: EHTParams,
  rng: SeededRandom,
  cellIndex: number
): void {
  const cell = state.cells[cellIndex];
  const cellType = getCellType(params, cell);

  const cellInput: CreateCellInput = {
    basalPoint: Vector2.from(cell.B),
    apicalPoint: Vector2.from(cell.A),
    nucleusPosition: Vector2.from(cell.pos),
  };

  const newCell = createCell(
    params,
    state,
    rng,
    cellInput,
    cellType,
    cell.typeIndex,
    cell
  );

  // Preserve the cell's ID
  newCell.id = cell.id;

  // Reset cycle-scoped properties while preserving already-lost adhesions.
  const h = params.general.h_init;
  newCell.R_hard = cellType.R_hard;
  newCell.eta_A = h / 2;
  newCell.eta_B = h / 2;
  newCell.has_A = cell.has_A;
  newCell.has_B = cell.has_B;
  newCell.is_running = false;
  newCell.running_mode = cell.running_mode;
  newCell.stiffness_apical_apical = cellType.stiffness_apical_apical;
  newCell.stiffness_straightness = cell.stiffness_straightness;
  newCell.stiffness_nuclei_apical = cell.has_A
    ? cellType.stiffness_nuclei_apical
    : cell.stiffness_nuclei_apical;
  newCell.stiffness_nuclei_basal = cell.has_B
    ? cellType.stiffness_nuclei_basal
    : cell.stiffness_nuclei_basal;
  newCell.k_apical_junction = cellType.k_apical_junction;

  // Inherit periodic event participation, re-sample one-time events
  const effectiveEvents = getEffectiveEvents(params.general, cellType);
  newCell.event_states = cell.event_states
    ? inheritEventStates(cell.event_states, effectiveEvents, rng, params.general, cellType, params.constants)
    : initializeEventStates(effectiveEvents, rng, params.general, cellType, params.constants);

  // Re-apply simulation-timed one-shot parameter changes whose effects should
  // survive a cycle reset alongside the preserved event state.
  for (const event of effectiveEvents) {
    if (event.type !== 'parameter_change') continue;
    if (!shouldPersistOneShotEventAcrossCycles(event)) continue;

    const priorState = cell.event_states?.[event.id];
    if (!priorState?.has_fired) continue;

    const priorValue = getCellParameter(cell, event.target_parameter);
    if (priorValue !== undefined) {
      setCellParameter(newCell, event.target_parameter, priorValue);
    }
  }
  newCell.has_reached_G2 = false;
  newCell.has_reached_mitosis = false;

  state.cells[cellIndex] = newCell;
}

/**
 * Process all events for the current timestep.
 */
export function processAllEvents(
  state: EHTSimulationState,
  params: EHTParams,
  dt: number,
  rng: SeededRandom
): void {
  processV2Events(state, params, dt, rng);
}
